29	// Deps holds the shared dependencies wired into every handler.
30	type Deps struct {
31		Cfg       *config.Config
32		DB        *pgxpool.Pool
33		StdDB     *sql.DB
34		Sessions  *sessions.Manager
35		Providers map[string]oauth.Provider
36		Users     *users.Store
37		Orgs      *organizations.Store
38	}
