40	// New returns a configured Gin engine with only the healthz route (no DB deps).
41	// Used by unit tests that do not need a real database.
42	func New() *gin.Engine {
43		r := gin.New()
44		r.Use(gin.Recovery())
45		r.Use(gin.Logger())
46	
47		r.GET("/healthz", func(c *gin.Context) {
48			c.Status(http.StatusNoContent)
49		})
50	
51		return r
