54	// NewWithDeps returns a configured Gin engine with all routes wired to real deps.
55	func NewWithDeps(deps *Deps) *gin.Engine {
56		r := gin.New()
57		r.Use(gin.Recovery())
58		r.Use(gin.Logger())
59	
60		// Session middleware: load session from store before the handler, save after.
61		sm := deps.Sessions.SessionManager()
62		r.Use(scsGinMiddleware(sm))
63	
64		r.GET("/healthz", func(c *gin.Context) {
65			c.Status(http.StatusNoContent)
66		})
67	
68		// Public OAuth routes.
69		r.GET("/auth/:provider/start", deps.handleAuthStart)
70		r.GET("/auth/:provider/callback", deps.handleAuthCallback)
71		r.POST("/auth/logout", deps.handleLogout)
72	
73		// Public user API.
74		r.GET("/api/me", deps.handleMe)
75	
76		// Internal service routes (Bearer token required).
77		internal := r.Group("/internal")
78		internal.Use(serviceauth.RequireServiceToken(deps.Cfg.UserServiceToken))
79		internal.POST("/sessions/validate", deps.handleValidateSession)
80	
81		return r
82	}
