84	// scsGinMiddleware integrates scs session management into Gin by using the
85	// lower-level Load/Commit/WriteSessionCookie API rather than LoadAndSave, which
86	// wraps the ResponseWriter in a way that conflicts with Gin's own wrapper.
87	func scsGinMiddleware(sm *scs.SessionManager) gin.HandlerFunc {
88		return func(c *gin.Context) {
89			// Extract the session token from the cookie.
90			var token string
91			if cookie, err := c.Request.Cookie(sm.Cookie.Name); err == nil {
92				token = cookie.Value
93			}
94	
95			// Load session data into a new context.
96			ctx, err := sm.Load(c.Request.Context(), token)
97			if err != nil {
98				log.Printf("session load: %v", err)
99				c.AbortWithStatus(http.StatusInternalServerError)
100				return
101			}
102	
103			// Replace the request's context so handlers see the session.
104			c.Request = c.Request.WithContext(ctx)
105	
106			// Process the request.
107			c.Next()
108	
109			// After the handler chain, commit session changes and set the cookie.
110			switch sm.Status(ctx) {
111			case scs.Modified:
112				sessionToken, expiry, commitErr := sm.Commit(ctx)
113				if commitErr != nil {
114					log.Printf("session commit: %v", commitErr)
115					return
116				}
117				sm.WriteSessionCookie(ctx, c.Writer, sessionToken, expiry)
118			case scs.Destroyed:
119				sm.WriteSessionCookie(ctx, c.Writer, "", zeroTime)
120			}
121		}
122	}
123	
124	// handleAuthStart generates a CSRF state token, stores it in the session, and
125	// redirects the browser to the IdP's authorization endpoint.
126	func (d *Deps) handleAuthStart(c *gin.Context) {
127		providerName := c.Param("provider")
128		provider, ok := d.Providers[providerName]
129		if !ok {
130			c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
131			return
132		}
133	
134		state, err := generateState()
135		if err != nil {
136			log.Printf("auth start: generate state: %v", err)
137			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
138			return
139		}
140	
141		d.Sessions.SetOAuthState(c.Request.Context(), state)
142	
143		url := provider.AuthCodeURL(state)
144		c.Redirect(http.StatusTemporaryRedirect, url)
145	}
146	
147	// handleAuthCallback exchanges the authorization code, upserts the user +
148	// auth_identity, consumes any matching invitation, sets the session cookie, and
149	// redirects to the frontend.
150	func (d *Deps) handleAuthCallback(c *gin.Context) {
151		providerName := c.Param("provider")
152		provider, ok := d.Providers[providerName]
153		if !ok {
154			c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
155			return
156		}
157	
158		ctx := c.Request.Context()
159	
160		// Verify CSRF state.
161		expectedState := d.Sessions.ConsumeOAuthState(ctx)
162		if expectedState == "" || c.Query("state") != expectedState {
163			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid state"})
164			return
165		}
166	
167		code := c.Query("code")
168		if code == "" {
169			c.JSON(http.StatusBadRequest, gin.H{"error": "missing code"})
170			return
171		}
172	
173		// Exchange code for token.
174		token, err := provider.Exchange(ctx, code)
175		if err != nil {
176			log.Printf("auth callback (%s): exchange: %v", providerName, err)
177			c.JSON(http.StatusBadGateway, gin.H{"error": "token exchange failed"})
178			return
179		}
180	
181		// Fetch user info from IdP.
182		info, err := provider.FetchUserInfo(ctx, token)
183		if err != nil {
184			log.Printf("auth callback (%s): userinfo: %v", providerName, err)
185			c.JSON(http.StatusBadGateway, gin.H{"error": "userinfo fetch failed"})
186			return
187		}
188	
189		// Upsert user + auth_identity and consume invitations inside a single transaction.
190		userID, err := d.upsertIdentityAndConsumeInvitations(ctx, provider.Name(), info)
191		if err != nil {
192			log.Printf("auth callback (%s): upsert identity: %v", providerName, err)
193			c.JSON(http.StatusInternalServerError, gin.H{"error": "identity upsert failed"})
194			return
195		}
196	
197		// Set session.
198		d.Sessions.SetUserID(ctx, userID)
199	
200		c.Redirect(http.StatusTemporaryRedirect, d.Cfg.FrontendBaseURL)
201	}
202	
203	// upsertIdentityAndConsumeInvitations runs inside a user_db transaction:
204	//  1. Find existing auth_identity by (provider, sub); if found, return its user_id.
205	//  2. Otherwise create/upsert user row and link auth_identity.
206	//  3. Check PLATFORM_ADMIN_EMAILS; if the verified email matches, ensure platform_admin membership.
207	//  4. Find and atomically accept any pending invitations for this email.
208	func (d *Deps) upsertIdentityAndConsumeInvitations(ctx context.Context, providerName string, info *oauth.UserInfo) (uuid.UUID, error) {
209		var userID uuid.UUID
210	
211		err := pgxTx(ctx, d.DB, func(tx pgx.Tx) error {
212			userStore := d.Users.WithTx(tx)
213			orgStore := d.Orgs.WithTx(tx)
214	
215			// Check for existing identity.
216			ai, err := userStore.FindByProviderSub(ctx, providerName, info.ProviderSub)
217			if err != nil && !errors.Is(err, pgx.ErrNoRows) {
218				return fmt.Errorf("find identity: %w", err)
219			}
220	
221			if ai != nil {
222				// Returning user — update profile.
223				userID = ai.UserID
224				if _, err := userStore.UpdateProfile(ctx, userID, info.DisplayName, info.AvatarURL); err != nil {
225					return fmt.Errorf("update profile: %w", err)
226				}
227			} else {
228				// New identity — create or match user by email.
229				u, err := userStore.EnsureUser(ctx, info.Email, info.DisplayName, info.AvatarURL)
230				if err != nil {
231					return fmt.Errorf("ensure user: %w", err)
232				}
233				userID = u.ID
234				if _, err := userStore.LinkAuthIdentity(ctx, userID, providerName, info.ProviderSub, info.Email, info.EmailVerified); err != nil {
235					return fmt.Errorf("link identity: %w", err)
236				}
237			}
238	
239			// PLATFORM_ADMIN_EMAILS check (only for verified emails).
240			if info.EmailVerified && d.isPlatformAdmin(info.Email) {
241				if err := d.ensurePlatformAdmin(ctx, userID, orgStore); err != nil {
242					return fmt.Errorf("platform admin: %w", err)
243				}
244			}
245	
246			// Consume pending invitations for this email.
247			if info.Email != "" {
248				invitations, err := orgStore.FindPendingInvitationsByEmail(ctx, info.Email)
249				if err != nil {
250					return fmt.Errorf("find invitations: %w", err)
251				}
252				for _, inv := range invitations {
253					if err := organizations.AcceptInvitation(ctx, tx, inv, userID); err != nil {
254						return fmt.Errorf("accept invitation %s: %w", inv.ID, err)
255					}
256				}
257			}
258	
259			return nil
260		})
261		if err != nil {
262			return uuid.Nil, err
263		}
264		return userID, nil
265	}
266	
267	// isPlatformAdmin checks whether the email is in the PLATFORM_ADMIN_EMAILS list.
268	func (d *Deps) isPlatformAdmin(email string) bool {
269		for _, e := range d.Cfg.PlatformAdminEmails {
270			if strings.EqualFold(e, email) {
271				return true
272			}
273		}
274		return false
275	}
276	
277	// ensurePlatformAdmin ensures the user has a platform_admin membership on the
278	// Kitelabs organization. If the org does not exist yet (T6 seed not run), this
279	// is a no-op; the auto-grant fires again on the user's next login after the seed runs.
280	// orgStore must be a tx-scoped store so the membership write is part of the outer transaction.
281	func (d *Deps) ensurePlatformAdmin(ctx context.Context, userID uuid.UUID, orgStore *organizations.Store) error {
282		org, err := orgStore.FindOrganizationBySlug(ctx, "kitelabs")
283		if err != nil {
284			if errors.Is(err, pgx.ErrNoRows) {
285				return nil
286			}
287			return err
288		}
289		_, err = orgStore.EnsureMembership(ctx, userID, org.ID, "platform_admin")
290		return err
291	}
292	
293	// handleLogout destroys the session and clears the cookie.
294	func (d *Deps) handleLogout(c *gin.Context) {
295		if err := d.Sessions.Destroy(c.Request.Context()); err != nil {
296			log.Printf("logout: destroy session: %v", err)
297		}
298		c.Status(http.StatusNoContent)
299	}
300	
301	// meResponse is the JSON body returned by GET /api/me.
302	type meResponse struct {
303		User                   meUser       `json:"user"`
304		Memberships            []meMembship `json:"memberships"`
305		AccessibleWorkspaceIDs []string     `json:"accessible_workspace_ids"`
306	}
307	
308	type meUser struct {
309		ID          string `json:"id"`
310		Email       string `json:"email"`
311		DisplayName string `json:"display_name"`
312		AvatarURL   string `json:"avatar_url"`
313	}
314	
315	type meMembship struct {
316		OrganizationID string `json:"organization_id"`
317		Role           string `json:"role"`
318	}
319	
320	// handleMe returns the current user's profile, memberships, and accessible workspace IDs.
321	func (d *Deps) handleMe(c *gin.Context) {
322		ctx := c.Request.Context()
323		userID := d.Sessions.GetUserID(ctx)
324		if userID == uuid.Nil {
325			c.JSON(http.StatusUnauthorized, gin.H{"error": "not authenticated"})
326			return
327		}
328	
329		u, err := d.Users.FindByID(ctx, userID)
330		if err != nil {
331			if errors.Is(err, pgx.ErrNoRows) {
332				c.JSON(http.StatusUnauthorized, gin.H{"error": "user not found"})
333				return
334			}
335			log.Printf("/api/me: find user: %v", err)
336			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
337			return
338		}
339	
340		memberships, err := d.Orgs.MembershipsByUser(ctx, userID)
341		if err != nil {
342			log.Printf("/api/me: memberships: %v", err)
343			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
344			return
345		}
346	
347		wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
348		if err != nil {
349			log.Printf("/api/me: accessible workspace IDs: %v", err)
350			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
351			return
352		}
353	
354		wsIDStrings := make([]string, len(wsIDs))
355		for i, id := range wsIDs {
356			wsIDStrings[i] = id.String()
357		}
358	
359		meMembs := make([]meMembship, len(memberships))
360		for i, m := range memberships {
361			meMembs[i] = meMembship{
362				OrganizationID: m.OrganizationID.String(),
363				Role:           m.Role,
364			}
365		}
366	
367		c.JSON(http.StatusOK, meResponse{
368			User: meUser{
369				ID:          u.ID.String(),
370				Email:       u.Email,
371				DisplayName: u.DisplayName,
372				AvatarURL:   u.AvatarURL,
373			},
374			Memberships:            meMembs,
375			AccessibleWorkspaceIDs: wsIDStrings,
376		})
377	}
378	
379	// validateSessionRequest is the body of POST /internal/sessions/validate.
380	type validateSessionRequest struct {
381		CookieValue string `json:"cookie_value" binding:"required"`
382	}
383	
384	// validateSessionResponse is returned on a successful session validation.
385	type validateSessionResponse struct {
386		UserID                 string   `json:"user_id"`
387		AccessibleWorkspaceIDs []string `json:"accessible_workspace_ids"`
388	}
389	
390	// handleValidateSession validates a session cookie and returns the user_id and
391	// accessible_workspace_ids. Called by workflow-backend's RequireAuth middleware.
392	func (d *Deps) handleValidateSession(c *gin.Context) {
393		var req validateSessionRequest
394		if err := c.ShouldBindJSON(&req); err != nil {
395			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
396			return
397		}
398	
399		ctx := c.Request.Context()
400		sm := d.Sessions.SessionManager()
401	
402		// Load the session using the token value from the request body.
403		// sm.Load returns an empty session context when the token is missing or expired.
404		loadedCtx, err := sm.Load(ctx, req.CookieValue)
405		if err != nil {
406			log.Printf("/internal/sessions/validate: load session: %v", err)
407			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
408			return
409		}
410	
411		userID := d.Sessions.GetUserID(loadedCtx)
412		if userID == uuid.Nil {
413			c.JSON(http.StatusUnauthorized, gin.H{"error": "session not found or expired"})
414			return
415		}
416	
417		wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
418		if err != nil {
419			log.Printf("/internal/sessions/validate: accessible workspace IDs: %v", err)
420			c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
421			return
422		}
423	
424		wsIDStrings := make([]string, len(wsIDs))
425		for i, id := range wsIDs {
426			wsIDStrings[i] = id.String()
427		}
428	
429		c.JSON(http.StatusOK, validateSessionResponse{
430			UserID:                 userID.String(),
431			AccessibleWorkspaceIDs: wsIDStrings,
432		})
433	}
434	
435	// generateState produces a cryptographically random OAuth CSRF state token.
436	func generateState() (string, error) {
437		b := make([]byte, 32)
438		if _, err := rand.Read(b); err != nil {
439			return "", err
440		}
441		return base64.URLEncoding.EncodeToString(b), nil
442	}
443	
444	// pgxTx runs fn inside a pgx transaction; rolls back on error.
445	func pgxTx(ctx context.Context, pool *pgxpool.Pool, fn func(pgx.Tx) error) error {
446		tx, err := pool.Begin(ctx)
447		if err != nil {
448			return err
449		}
450		defer func() { _ = tx.Rollback(ctx) }()
451		if err := fn(tx); err != nil {
452			return err
453		}
454		return tx.Commit(ctx)
455	}
