// Package httpapi wires together all HTTP routes for user-service.
package httpapi

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/base64"
	"errors"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/alexedwards/scs/v2"
	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/tiendv89/user-service/internal/config"
	"github.com/tiendv89/user-service/internal/oauth"
	"github.com/tiendv89/user-service/internal/organizations"
	"github.com/tiendv89/user-service/internal/serviceauth"
	"github.com/tiendv89/user-service/internal/sessions"
	"github.com/tiendv89/user-service/internal/users"
)

// Deps holds the shared dependencies wired into every handler.
type Deps struct {
	Cfg       *config.Config
	DB        *pgxpool.Pool
	StdDB     *sql.DB
	Sessions  *sessions.Manager
	Providers map[string]oauth.Provider
	Users     *users.Store
	Orgs      *organizations.Store
}

// New returns a configured Gin engine with only the healthz route (no DB deps).
// Used by unit tests that do not need a real database.
func New() *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	r.Use(gin.Logger())

	r.GET("/healthz", func(c *gin.Context) {
		c.Status(http.StatusNoContent)
	})

	return r
}

// NewWithDeps returns a configured Gin engine with all routes wired to real deps.
func NewWithDeps(deps *Deps) *gin.Engine {
	r := gin.New()
	r.Use(gin.Recovery())
	r.Use(gin.Logger())

	// Session middleware: load session from store before the handler, save after.
	sm := deps.Sessions.SessionManager()
	r.Use(scsGinMiddleware(sm))

	r.GET("/healthz", func(c *gin.Context) {
		c.Status(http.StatusNoContent)
	})

	// Public OAuth routes.
	r.GET("/auth/:provider/start", deps.handleAuthStart)
	r.GET("/auth/:provider/callback", deps.handleAuthCallback)
	r.POST("/auth/logout", deps.handleLogout)

	// Public user API.
	r.GET("/api/me", deps.handleMe)

	// Internal service routes (Bearer token required).
	internal := r.Group("/internal")
	internal.Use(serviceauth.RequireServiceToken(deps.Cfg.UserServiceToken))
	internal.POST("/sessions/validate", deps.handleValidateSession)

	return r
}

// scsGinMiddleware integrates scs session management into Gin by using the
// lower-level Load/Commit/WriteSessionCookie API rather than LoadAndSave, which
// wraps the ResponseWriter in a way that conflicts with Gin's own wrapper.
func scsGinMiddleware(sm *scs.SessionManager) gin.HandlerFunc {
	return func(c *gin.Context) {
		// Extract the session token from the cookie.
		var token string
		if cookie, err := c.Request.Cookie(sm.Cookie.Name); err == nil {
			token = cookie.Value
		}

		// Load session data into a new context.
		ctx, err := sm.Load(c.Request.Context(), token)
		if err != nil {
			log.Printf("session load: %v", err)
			c.AbortWithStatus(http.StatusInternalServerError)
			return
		}

		// Replace the request's context so handlers see the session.
		c.Request = c.Request.WithContext(ctx)

		// Process the request.
		c.Next()

		// After the handler chain, commit session changes and set the cookie.
		switch sm.Status(ctx) {
		case scs.Modified:
			sessionToken, expiry, commitErr := sm.Commit(ctx)
			if commitErr != nil {
				log.Printf("session commit: %v", commitErr)
				return
			}
			sm.WriteSessionCookie(ctx, c.Writer, sessionToken, expiry)
		case scs.Destroyed:
			sm.WriteSessionCookie(ctx, c.Writer, "", zeroTime)
		}
	}
}

// handleAuthStart generates a CSRF state token, stores it in the session, and
// redirects the browser to the IdP's authorization endpoint.
func (d *Deps) handleAuthStart(c *gin.Context) {
	providerName := c.Param("provider")
	provider, ok := d.Providers[providerName]
	if !ok {
		c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
		return
	}

	state, err := generateState()
	if err != nil {
		log.Printf("auth start: generate state: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	d.Sessions.SetOAuthState(c.Request.Context(), state)

	url := provider.AuthCodeURL(state)
	c.Redirect(http.StatusTemporaryRedirect, url)
}

// handleAuthCallback exchanges the authorization code, upserts the user +
// auth_identity, consumes any matching invitation, sets the session cookie, and
// redirects to the frontend.
func (d *Deps) handleAuthCallback(c *gin.Context) {
	providerName := c.Param("provider")
	provider, ok := d.Providers[providerName]
	if !ok {
		c.JSON(http.StatusBadRequest, gin.H{"error": "unknown provider"})
		return
	}

	ctx := c.Request.Context()

	// Verify CSRF state.
	expectedState := d.Sessions.ConsumeOAuthState(ctx)
	if expectedState == "" || c.Query("state") != expectedState {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid state"})
		return
	}

	code := c.Query("code")
	if code == "" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "missing code"})
		return
	}

	// Exchange code for token.
	token, err := provider.Exchange(ctx, code)
	if err != nil {
		log.Printf("auth callback (%s): exchange: %v", providerName, err)
		c.JSON(http.StatusBadGateway, gin.H{"error": "token exchange failed"})
		return
	}

	// Fetch user info from IdP.
	info, err := provider.FetchUserInfo(ctx, token)
	if err != nil {
		log.Printf("auth callback (%s): userinfo: %v", providerName, err)
		c.JSON(http.StatusBadGateway, gin.H{"error": "userinfo fetch failed"})
		return
	}

	// Upsert user + auth_identity and consume invitations inside a single transaction.
	userID, err := d.upsertIdentityAndConsumeInvitations(ctx, provider.Name(), info)
	if err != nil {
		log.Printf("auth callback (%s): upsert identity: %v", providerName, err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "identity upsert failed"})
		return
	}

	// Set session.
	d.Sessions.SetUserID(ctx, userID)

	c.Redirect(http.StatusTemporaryRedirect, d.Cfg.FrontendBaseURL)
}

// upsertIdentityAndConsumeInvitations runs inside a user_db transaction:
//  1. Find existing auth_identity by (provider, sub); if found, return its user_id.
//  2. Otherwise create/upsert user row and link auth_identity.
//  3. Check PLATFORM_ADMIN_EMAILS; if the verified email matches, ensure platform_admin membership.
//  4. Find and atomically accept any pending invitations for this email.
func (d *Deps) upsertIdentityAndConsumeInvitations(ctx context.Context, providerName string, info *oauth.UserInfo) (uuid.UUID, error) {
	var userID uuid.UUID

	err := pgxTx(ctx, d.DB, func(tx pgx.Tx) error {
		userStore := d.Users.WithTx(tx)
		orgStore := d.Orgs.WithTx(tx)

		// Check for existing identity.
		ai, err := userStore.FindByProviderSub(ctx, providerName, info.ProviderSub)
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return fmt.Errorf("find identity: %w", err)
		}

		if ai != nil {
			// Returning user — update profile.
			userID = ai.UserID
			if _, err := userStore.UpdateProfile(ctx, userID, info.DisplayName, info.AvatarURL); err != nil {
				return fmt.Errorf("update profile: %w", err)
			}
		} else {
			// New identity — create or match user by email.
			u, err := userStore.EnsureUser(ctx, info.Email, info.DisplayName, info.AvatarURL)
			if err != nil {
				return fmt.Errorf("ensure user: %w", err)
			}
			userID = u.ID
			if _, err := userStore.LinkAuthIdentity(ctx, userID, providerName, info.ProviderSub, info.Email, info.EmailVerified); err != nil {
				return fmt.Errorf("link identity: %w", err)
			}
		}

		// PLATFORM_ADMIN_EMAILS check (only for verified emails).
		if info.EmailVerified && d.isPlatformAdmin(info.Email) {
			if err := d.ensurePlatformAdmin(ctx, userID, orgStore); err != nil {
				return fmt.Errorf("platform admin: %w", err)
			}
		}

		// Consume pending invitations for this email.
		if info.Email != "" {
			invitations, err := orgStore.FindPendingInvitationsByEmail(ctx, info.Email)
			if err != nil {
				return fmt.Errorf("find invitations: %w", err)
			}
			for _, inv := range invitations {
				if err := organizations.AcceptInvitation(ctx, tx, inv, userID); err != nil {
					return fmt.Errorf("accept invitation %s: %w", inv.ID, err)
				}
			}
		}

		return nil
	})
	if err != nil {
		return uuid.Nil, err
	}
	return userID, nil
}

// isPlatformAdmin checks whether the email is in the PLATFORM_ADMIN_EMAILS list.
func (d *Deps) isPlatformAdmin(email string) bool {
	for _, e := range d.Cfg.PlatformAdminEmails {
		if strings.EqualFold(e, email) {
			return true
		}
	}
	return false
}

// ensurePlatformAdmin ensures the user has a platform_admin membership on the
// Kitelabs organization. If the org does not exist yet (T6 seed not run), this
// is a no-op; the auto-grant fires again on the user's next login after the seed runs.
// orgStore must be a tx-scoped store so the membership write is part of the outer transaction.
func (d *Deps) ensurePlatformAdmin(ctx context.Context, userID uuid.UUID, orgStore *organizations.Store) error {
	org, err := orgStore.FindOrganizationBySlug(ctx, "kitelabs")
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil
		}
		return err
	}
	_, err = orgStore.EnsureMembership(ctx, userID, org.ID, "platform_admin")
	return err
}

// handleLogout destroys the session and clears the cookie.
func (d *Deps) handleLogout(c *gin.Context) {
	if err := d.Sessions.Destroy(c.Request.Context()); err != nil {
		log.Printf("logout: destroy session: %v", err)
	}
	c.Status(http.StatusNoContent)
}

// meResponse is the JSON body returned by GET /api/me.
type meResponse struct {
	User                   meUser       `json:"user"`
	Memberships            []meMembship `json:"memberships"`
	AccessibleWorkspaceIDs []string     `json:"accessible_workspace_ids"`
}

type meUser struct {
	ID          string `json:"id"`
	Email       string `json:"email"`
	DisplayName string `json:"display_name"`
	AvatarURL   string `json:"avatar_url"`
}

type meMembship struct {
	OrganizationID string `json:"organization_id"`
	Role           string `json:"role"`
}

// handleMe returns the current user's profile, memberships, and accessible workspace IDs.
func (d *Deps) handleMe(c *gin.Context) {
	ctx := c.Request.Context()
	userID := d.Sessions.GetUserID(ctx)
	if userID == uuid.Nil {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "not authenticated"})
		return
	}

	u, err := d.Users.FindByID(ctx, userID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "user not found"})
			return
		}
		log.Printf("/api/me: find user: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	memberships, err := d.Orgs.MembershipsByUser(ctx, userID)
	if err != nil {
		log.Printf("/api/me: memberships: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
	if err != nil {
		log.Printf("/api/me: accessible workspace IDs: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	wsIDStrings := make([]string, len(wsIDs))
	for i, id := range wsIDs {
		wsIDStrings[i] = id.String()
	}

	meMembs := make([]meMembship, len(memberships))
	for i, m := range memberships {
		meMembs[i] = meMembship{
			OrganizationID: m.OrganizationID.String(),
			Role:           m.Role,
		}
	}

	c.JSON(http.StatusOK, meResponse{
		User: meUser{
			ID:          u.ID.String(),
			Email:       u.Email,
			DisplayName: u.DisplayName,
			AvatarURL:   u.AvatarURL,
		},
		Memberships:            meMembs,
		AccessibleWorkspaceIDs: wsIDStrings,
	})
}

// validateSessionRequest is the body of POST /internal/sessions/validate.
type validateSessionRequest struct {
	CookieValue string `json:"cookie_value" binding:"required"`
}

// validateSessionResponse is returned on a successful session validation.
type validateSessionResponse struct {
	UserID                 string   `json:"user_id"`
	AccessibleWorkspaceIDs []string `json:"accessible_workspace_ids"`
}

// handleValidateSession validates a session cookie and returns the user_id and
// accessible_workspace_ids. Called by workflow-backend's RequireAuth middleware.
func (d *Deps) handleValidateSession(c *gin.Context) {
	var req validateSessionRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}

	ctx := c.Request.Context()
	sm := d.Sessions.SessionManager()

	// Load the session using the token value from the request body.
	// sm.Load returns an empty session context when the token is missing or expired.
	loadedCtx, err := sm.Load(ctx, req.CookieValue)
	if err != nil {
		log.Printf("/internal/sessions/validate: load session: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	userID := d.Sessions.GetUserID(loadedCtx)
	if userID == uuid.Nil {
		c.JSON(http.StatusUnauthorized, gin.H{"error": "session not found or expired"})
		return
	}

	wsIDs, err := d.Orgs.AccessibleWorkspaceIDs(ctx, userID)
	if err != nil {
		log.Printf("/internal/sessions/validate: accessible workspace IDs: %v", err)
		c.JSON(http.StatusInternalServerError, gin.H{"error": "internal error"})
		return
	}

	wsIDStrings := make([]string, len(wsIDs))
	for i, id := range wsIDs {
		wsIDStrings[i] = id.String()
	}

	c.JSON(http.StatusOK, validateSessionResponse{
		UserID:                 userID.String(),
		AccessibleWorkspaceIDs: wsIDStrings,
	})
}

// generateState produces a cryptographically random OAuth CSRF state token.
func generateState() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return base64.URLEncoding.EncodeToString(b), nil
}

// pgxTx runs fn inside a pgx transaction; rolls back on error.
func pgxTx(ctx context.Context, pool *pgxpool.Pool, fn func(pgx.Tx) error) error {
	tx, err := pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

