package httpapi

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"

	"golang.org/x/oauth2"

	"github.com/tiendv89/user-service/internal/oauth"
)

// mockProvider is a test double for oauth.Provider.
type mockProvider struct {
	name     string
	authURL  string
	userInfo *oauth.UserInfo
	exchErr  error
	infoErr  error
}

func (m *mockProvider) Name() string { return m.name }
func (m *mockProvider) AuthCodeURL(state string, _ ...oauth2.AuthCodeOption) string {
	return m.authURL + "?state=" + state
}
func (m *mockProvider) Exchange(_ context.Context, _ string) (*oauth2.Token, error) {
	return &oauth2.Token{AccessToken: "tok"}, m.exchErr
}
func (m *mockProvider) FetchUserInfo(_ context.Context, _ *oauth2.Token) (*oauth.UserInfo, error) {
	return m.userInfo, m.infoErr
}

func TestHandleAuthStart_UnknownProvider_Returns400(t *testing.T) {
	d := &Deps{
		Providers: map[string]oauth.Provider{},
	}

	// Test the pure provider-lookup logic without a full HTTP stack.
	_, ok := d.Providers["unknown"]
	if ok {
		t.Fatal("expected unknown provider lookup to fail")
	}
}

func TestHandleAuthStart_KnownProvider_GeneratesState(t *testing.T) {
	mock := &mockProvider{name: "google", authURL: "https://accounts.google.com/o/oauth2/auth"}
	providers := map[string]oauth.Provider{"google": mock}
	_ = providers

	// Test that generateState produces a non-empty value (integration with the real
	// generateState function, which is in the same package).
	for i := 0; i < 10; i++ {
		state, err := generateState()
		if err != nil {
			t.Fatalf("generateState[%d]: %v", i, err)
		}
		if state == "" {
			t.Fatal("empty state")
		}
	}
}

func TestAuthStart_UnknownProvider_404(t *testing.T) {
	// Verify that the healthz route exists and unknown auth provider returns a
	// meaningful response. We use a plain New() router (no DB).
	r := New()

	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/auth/unknown_provider/start", nil)
	r.ServeHTTP(w, req)

	// New() does not register /auth/* routes, so Gin returns 404.
	if w.Code != http.StatusNotFound {
		t.Fatalf("expected 404 for unregistered auth route, got %d", w.Code)
	}
}

package httpapi

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/tiendv89/user-service/internal/serviceauth"
)

// TestValidateSession_MissingToken exercises the service-auth middleware
// directly (no DB needed).
func TestValidateSession_MissingToken_Returns401(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(serviceauth.RequireServiceToken("correct-token"))
	r.POST("/internal/sessions/validate", func(c *gin.Context) {
		c.Status(http.StatusOK)
	})

	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	// No Authorization header.
	r.ServeHTTP(w, req)

	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 when no service token, got %d", w.Code)
	}
}

func TestValidateSession_WrongToken_Returns401(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(serviceauth.RequireServiceToken("correct-token"))
	r.POST("/internal/sessions/validate", func(c *gin.Context) {
		c.Status(http.StatusOK)
	})

	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer wrong-token")
	r.ServeHTTP(w, req)

	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 with wrong token, got %d", w.Code)
	}
}

func TestValidateSession_ValidToken_Passes(t *testing.T) {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.Use(serviceauth.RequireServiceToken("correct-token"))
	r.POST("/internal/sessions/validate", func(c *gin.Context) {
		// Stub handler — just return 200.
		c.Status(http.StatusOK)
	})

	body, _ := json.Marshal(map[string]string{"cookie_value": "some-cookie"})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	req.Header.Set("Authorization", "Bearer correct-token")
	req.Header.Set("Content-Type", "application/json")
	r.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Fatalf("expected 200 with correct token, got %d", w.Code)
	}
}

