1	// Package users provides CRUD for the users and auth_identities tables.
2	package users
3	
4	import (
5		"context"
6		"errors"
7		"time"
8	
9		"github.com/google/uuid"
10		"github.com/jackc/pgx/v5"
11		"github.com/jackc/pgx/v5/pgxpool"
12	)
13	
14	// DBTX is satisfied by both *pgxpool.Pool and pgx.Tx.
15	type DBTX interface {
16		QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
17		Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
18	}
19	
20	// User represents a platform user.
21	type User struct {
22		ID          uuid.UUID
23		Email       string
24		DisplayName string
25		AvatarURL   string
26		CreatedAt   time.Time
27		UpdatedAt   time.Time
28	}
29	
30	// AuthIdentity links a user to an OAuth provider identity.
31	type AuthIdentity struct {
32		ID            uuid.UUID
33		UserID        uuid.UUID
34		Provider      string
35		ProviderSub   string
36		Email         string
37		EmailVerified bool
38		CreatedAt     time.Time
39	}
40	
41	// Store performs user and auth_identity operations.
42	type Store struct {
43		db DBTX
44	}
45	
46	// New creates a new Store backed by a connection pool.
47	func New(db *pgxpool.Pool) *Store {
48		return &Store{db: db}
49	}
50	
51	// WithTx returns a new Store that executes all queries inside tx.
52	func (s *Store) WithTx(tx pgx.Tx) *Store {
53		return &Store{db: tx}
54	}
55	
56	// EnsureUser upserts a user by email. If the user already exists (matched by
57	// lower(email)), it returns the existing record. Otherwise it creates a new one.
58	// On conflict the display_name and avatar_url are updated.
59	func (s *Store) EnsureUser(ctx context.Context, email, displayName, avatarURL string) (*User, error) {
60		row := s.db.QueryRow(ctx, `
61			INSERT INTO users (email, display_name, avatar_url)
62			VALUES ($1, $2, $3)
63			ON CONFLICT DO NOTHING
64			RETURNING id, email, display_name, avatar_url, created_at, updated_at`,
65			email, displayName, avatarURL,
66		)
67		u, err := scanUser(row)
68		if err != nil {
69			if errors.Is(err, pgx.ErrNoRows) {
70				// Row already existed — fetch it.
71				return s.FindByEmail(ctx, email)
72			}
73			return nil, err
74		}
75		return u, nil
76	}
77	
78	// FindByID looks up a user by primary key.
79	func (s *Store) FindByID(ctx context.Context, id uuid.UUID) (*User, error) {
80		row := s.db.QueryRow(ctx, `
81			SELECT id, email, display_name, avatar_url, created_at, updated_at
82			FROM users WHERE id = $1`, id)
83		return scanUser(row)
84	}
85	
86	// FindByEmail looks up a user by email (case-insensitive).
87	func (s *Store) FindByEmail(ctx context.Context, email string) (*User, error) {
88		row := s.db.QueryRow(ctx, `
89			SELECT id, email, display_name, avatar_url, created_at, updated_at
90			FROM users WHERE lower(email) = lower($1)`, email)
91		return scanUser(row)
92	}
93	
94	// UpdateProfile updates the display_name, avatar_url and updated_at for an existing user.
95	func (s *Store) UpdateProfile(ctx context.Context, id uuid.UUID, displayName, avatarURL string) (*User, error) {
96		row := s.db.QueryRow(ctx, `
97			UPDATE users SET display_name = $2, avatar_url = $3, updated_at = now()
98			WHERE id = $1
99			RETURNING id, email, display_name, avatar_url, created_at, updated_at`,
100			id, displayName, avatarURL,
101		)
102		return scanUser(row)
103	}
104	
105	// LinkAuthIdentity inserts an auth_identity row. If one already exists for
106	// (provider, provider_sub) it is returned unchanged.
107	func (s *Store) LinkAuthIdentity(ctx context.Context, userID uuid.UUID, provider, providerSub, email string, emailVerified bool) (*AuthIdentity, error) {
108		row := s.db.QueryRow(ctx, `
109			INSERT INTO auth_identities (user_id, provider, provider_sub, email, email_verified)
110			VALUES ($1, $2, $3, $4, $5)
111			ON CONFLICT (provider, provider_sub) DO NOTHING
112			RETURNING id, user_id, provider, provider_sub, email, email_verified, created_at`,
113			userID, provider, providerSub, email, emailVerified,
114		)
115		ai, err := scanAuthIdentity(row)
116		if err != nil {
117			if errors.Is(err, pgx.ErrNoRows) {
118				return s.FindByProviderSub(ctx, provider, providerSub)
119			}
120			return nil, err
121		}
122		return ai, nil
123	}
124	
125	// FindByProviderSub looks up an auth_identity by (provider, provider_sub).
126	func (s *Store) FindByProviderSub(ctx context.Context, provider, providerSub string) (*AuthIdentity, error) {
127		row := s.db.QueryRow(ctx, `
128			SELECT id, user_id, provider, provider_sub, email, email_verified, created_at
129			FROM auth_identities WHERE provider = $1 AND provider_sub = $2`,
130			provider, providerSub,
131		)
132		ai, err := scanAuthIdentity(row)
133		if err != nil {
134			return nil, err
135		}
136		return ai, nil
137	}
138	
139	func scanUser(row pgx.Row) (*User, error) {
140		var u User
141		var displayName, avatarURL *string
142		err := row.Scan(&u.ID, &u.Email, &displayName, &avatarURL, &u.CreatedAt, &u.UpdatedAt)
143		if err != nil {
144			return nil, err
145		}
146		if displayName != nil {
147			u.DisplayName = *displayName
148		}
149		if avatarURL != nil {
150			u.AvatarURL = *avatarURL
151		}
152		return &u, nil
153	}
154	
155	func scanAuthIdentity(row pgx.Row) (*AuthIdentity, error) {
156		var ai AuthIdentity
157		var email *string
158		var emailVerified *bool
159		err := row.Scan(&ai.ID, &ai.UserID, &ai.Provider, &ai.ProviderSub, &email, &emailVerified, &ai.CreatedAt)
160		if err != nil {
161			return nil, err
162		}
163		if email != nil {
164			ai.Email = *email
165		}
166		if emailVerified != nil {
167			ai.EmailVerified = *emailVerified
168		}
169		return &ai, nil
170	}
