package httpapi

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"

	"github.com/tiendv89/user-service/internal/config"
	"github.com/tiendv89/user-service/internal/organizations"
	"github.com/tiendv89/user-service/internal/serviceauth"
	"github.com/tiendv89/user-service/internal/sessions"
	"github.com/tiendv89/user-service/internal/users"
)

// emptyDBTX is a no-op DBTX that returns zero rows for all queries.
// It satisfies both users.DBTX and organizations.DBTX.
type emptyDBTX struct{}

func (e *emptyDBTX) QueryRow(_ context.Context, _ string, _ ...any) pgx.Row {
	return &emptyRow{}
}

func (e *emptyDBTX) Query(_ context.Context, _ string, _ ...any) (pgx.Rows, error) {
	return &emptyRows{}, nil
}

func (e *emptyDBTX) Exec(_ context.Context, _ string, _ ...any) (pgconn.CommandTag, error) {
	return pgconn.CommandTag{}, nil
}

type emptyRow struct{}

func (r *emptyRow) Scan(_ ...any) error { return pgx.ErrNoRows }

type emptyRows struct{}

func (r *emptyRows) Close()                                    {}
func (r *emptyRows) Err() error                                { return nil }
func (r *emptyRows) CommandTag() pgconn.CommandTag             { return pgconn.CommandTag{} }
func (r *emptyRows) FieldDescriptions() []pgconn.FieldDescription { return nil }
func (r *emptyRows) Next() bool                                { return false }
func (r *emptyRows) Scan(_ ...any) error                       { return pgx.ErrNoRows }
func (r *emptyRows) Values() ([]any, error)                    { return nil, nil }
func (r *emptyRows) RawValues() [][]byte                       { return nil }
func (r *emptyRows) Conn() *pgx.Conn                           { return nil }

// buildValidateRouter creates a Gin router wired to handleValidateSession with
// the provided sessions.Manager and organizations.Store. No real DB needed.
func buildValidateRouter(sessMgr *sessions.Manager, orgStore *organizations.Store, serviceToken string) *gin.Engine {
	gin.SetMode(gin.TestMode)
	cfg := &config.Config{UserServiceToken: serviceToken}
	deps := &Deps{
		Cfg:      cfg,
		Sessions: sessMgr,
		Users:    users.NewFromDBTX(&emptyDBTX{}),
		Orgs:     orgStore,
	}

	r := gin.New()
	r.Use(scsGinMiddleware(sessMgr.SessionManager()))
	internal := r.Group("/internal")
	internal.Use(serviceauth.RequireServiceToken(deps.Cfg.UserServiceToken))
	internal.POST("/sessions/validate", deps.handleValidateSession)
	return r
}

// seedSession creates a new session with the given user ID and returns the token.
func seedSession(t *testing.T, mgr *sessions.Manager, userID uuid.UUID) string {
	t.Helper()
	sm := mgr.SessionManager()
	ctx, err := sm.Load(context.Background(), "")
	if err != nil {
		t.Fatalf("seedSession: Load: %v", err)
	}
	mgr.SetUserID(ctx, userID)
	token, _, err := sm.Commit(ctx)
	if err != nil {
		t.Fatalf("seedSession: Commit: %v", err)
	}
	return token
}

func sendValidate(r *gin.Engine, token, serviceToken string) *httptest.ResponseRecorder {
	body, _ := json.Marshal(map[string]string{"cookie_value": token})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/internal/sessions/validate", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+serviceToken)
	r.ServeHTTP(w, req)
	return w
}

// TestValidateSession_ValidSession_Returns200 verifies that a valid session token
// containing a user_id returns 200 with the correct user_id and null workspace IDs
// (unrestricted — no workspace_membership rows exist for the user).
func TestValidateSession_ValidSession_Returns200(t *testing.T) {
	mgr := sessions.NewForTest()
	orgStore := organizations.NewFromDBTX(&emptyDBTX{})
	r := buildValidateRouter(mgr, orgStore, "svc-token")

	userID := uuid.New()
	token := seedSession(t, mgr, userID)

	w := sendValidate(r, token, "svc-token")
	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", w.Code, w.Body.String())
	}

	var resp validateSessionResponse
	if err := json.Unmarshal(w.Body.Bytes(), &resp); err != nil {
		t.Fatalf("unmarshal response: %v", err)
	}
	if resp.UserID != userID.String() {
		t.Fatalf("user_id mismatch: got %q, want %q", resp.UserID, userID.String())
	}
	// nil wsIDs → JSON null (unrestricted). Make sure we don't get [].
	var raw map[string]any
	if err := json.Unmarshal(w.Body.Bytes(), &raw); err != nil {
		t.Fatalf("unmarshal raw: %v", err)
	}
	if wsRaw, ok := raw["accessible_workspace_ids"]; ok && wsRaw != nil {
		t.Fatalf("expected null accessible_workspace_ids for unrestricted user, got %v", wsRaw)
	}
}

// TestValidateSession_AbsentToken_Returns401 verifies that an empty cookie_value
// (no session exists) returns 401.
func TestValidateSession_AbsentToken_Returns401(t *testing.T) {
	mgr := sessions.NewForTest()
	orgStore := organizations.NewFromDBTX(&emptyDBTX{})
	r := buildValidateRouter(mgr, orgStore, "svc-token")

	w := sendValidate(r, "", "svc-token")
	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 for absent session token, got %d: %s", w.Code, w.Body.String())
	}
}

// TestValidateSession_UnknownToken_Returns401 verifies that a token that does not
// map to any session returns 401.
func TestValidateSession_UnknownToken_Returns401(t *testing.T) {
	mgr := sessions.NewForTest()
	orgStore := organizations.NewFromDBTX(&emptyDBTX{})
	r := buildValidateRouter(mgr, orgStore, "svc-token")

	w := sendValidate(r, "non-existent-token-xyz", "svc-token")
	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 for unknown session token, got %d: %s", w.Code, w.Body.String())
	}
}

// TestValidateSession_SessionNoUserID_Returns401 verifies that a session that
// exists but has no user_id key set returns 401.
func TestValidateSession_SessionNoUserID_Returns401(t *testing.T) {
	mgr := sessions.NewForTest()
	orgStore := organizations.NewFromDBTX(&emptyDBTX{})
	r := buildValidateRouter(mgr, orgStore, "svc-token")

	// Seed a session without setting user_id.
	sm := mgr.SessionManager()
	ctx, _ := sm.Load(context.Background(), "")
	sm.Put(ctx, "some_other_key", "value")
	token, _, err := sm.Commit(ctx)
	if err != nil {
		t.Fatalf("Commit: %v", err)
	}

	w := sendValidate(r, token, "svc-token")
	if w.Code != http.StatusUnauthorized {
		t.Fatalf("expected 401 when session has no user_id, got %d: %s", w.Code, w.Body.String())
	}
}

