	if dsn == "" {
		t.Skip("TEST_DSN not set — skipping DB integration test")
	}
	return dsn
}

// idpServer spins up a minimal mock OAuth IdP that serves:
//   - POST /token  → access token response
//   - GET  /userinfo → user info JSON (Google-style)
func idpServer(t *testing.T, userInfoBody string) *httptest.Server {
