func TestAuthCallback_NewUser_CreatesIdentityAndSetsSession(t *testing.T) {
	dsn := requireTestDSN(t)

	// ── DB setup ──────────────────────────────────────────────────────────────
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatalf("pgxpool.New: %v", err)
	}
	t.Cleanup(pool.Close)

	stdDB, err := sql.Open("pgx", dsn)
	if err != nil {
		t.Fatalf("sql.Open: %v", err)
	}
	t.Cleanup(func() { _ = stdDB.Close() })

	// ── Mock IdP ──────────────────────────────────────────────────────────────
	userInfoJSON := `{
		"sub": "google-sub-test-001",
		"email": "callback-test@example.com",
		"email_verified": true,
		"name": "Callback Test User",
		"picture": "https://example.com/pic.jpg"
	}`
	idp := idpServer(t, userInfoJSON)

	// ── Build mock provider pointing at in-process IdP ────────────────────────
	provider := &mockCallbackProvider{
		name:      "google",
		tokenURL:  idp.URL + "/token",
		userinfoURL: idp.URL + "/userinfo",
	}

	// ── Sessions (in-memory for test isolation) ───────────────────────────────
	sessMgr := sessions.NewForTest()
	sm := sessMgr.SessionManager()

	// Pre-seed OAuth state into the session so verifyState passes.
	stateCtx, err := sm.Load(ctx, "")
	if err != nil {
		t.Fatalf("sm.Load: %v", err)
	}
	const testState = "test-state-xyz"
	sessMgr.SetOAuthState(stateCtx, testState)
	sessionToken, _, err := sm.Commit(stateCtx)
	if err != nil {
		t.Fatalf("sm.Commit: %v", err)
	}

	// ── Deps ──────────────────────────────────────────────────────────────────
	cfg := &config.Config{
		FrontendBaseURL:     "https://app.example.com",
		UserServiceToken:    "svc-token",
		PlatformAdminEmails: nil,
	}
	deps := &Deps{
		Cfg:      cfg,
		DB:       pool,
		Sessions: sessMgr,
		Users:    users.New(pool),
		Orgs:     organizations.New(pool),
		Providers: map[string]oauth.Provider{
			"google": provider,
		},
	}

	// ── HTTP server ───────────────────────────────────────────────────────────
	r := New()
	r.Use(scsGinMiddleware(sm))
	r.GET("/auth/:provider/callback", deps.handleAuthCallback)

	// ── Request ───────────────────────────────────────────────────────────────
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet,
		"/auth/google/callback?code=test-code&state="+testState, nil)
	// Attach the session cookie so the handler can read the pre-seeded state.
	req.AddCookie(&http.Cookie{
		Name:  sm.Cookie.Name,
		Value: sessionToken,
	})
	r.ServeHTTP(w, req)

	// ── Assertions ────────────────────────────────────────────────────────────
	if w.Code != http.StatusTemporaryRedirect {
		t.Fatalf("expected 307 redirect, got %d: %s", w.Code, w.Body.String())
	}
	if loc := w.Header().Get("Location"); loc != cfg.FrontendBaseURL {
		t.Fatalf("redirect location: got %q, want %q", loc, cfg.FrontendBaseURL)
	}

	// Verify a Set-Cookie header was written (session set after login).
	var gotSessionCookie bool
	for _, c := range w.Result().Cookies() {
		if c.Name == sm.Cookie.Name {
			gotSessionCookie = true
		}
	}
	if !gotSessionCookie {
		t.Fatalf("expected session cookie to be set after callback, cookies: %v", w.Result().Cookies())
	}

	// Verify user + auth_identity rows were created in the DB.
	var userID string
	err = pool.QueryRow(ctx,
		`SELECT id FROM users WHERE lower(email) = lower($1)`,
		"callback-test@example.com",
	).Scan(&userID)
	if err != nil {
		t.Fatalf("user row not found: %v", err)
	}

	var identityID string
	err = pool.QueryRow(ctx,
		`SELECT id FROM auth_identities WHERE provider = $1 AND provider_sub = $2`,
		"google", "google-sub-test-001",
	).Scan(&identityID)
	if err != nil {
		t.Fatalf("auth_identity row not found: %v", err)
	}

	t.Cleanup(func() {
		_, _ = pool.Exec(ctx, `DELETE FROM auth_identities WHERE provider_sub = 'google-sub-test-001'`)
		_, _ = pool.Exec(ctx, `DELETE FROM users WHERE lower(email) = lower('callback-test@example.com')`)
	})
}

// TestAuthCallback_InvitationAcceptance verifies that a pending invitation is
// consumed atomically during the OAuth callback flow.
func TestAuthCallback_InvitationAcceptance(t *testing.T) {
	dsn := requireTestDSN(t)

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatalf("pgxpool.New: %v", err)
	}
	t.Cleanup(pool.Close)

	// ── Seed an organization + invitation ─────────────────────────────────────
	var orgID string
	err = pool.QueryRow(ctx,
		`INSERT INTO organizations (slug, name) VALUES ('test-invite-org', 'Test Invite Org')
		 RETURNING id`,
	).Scan(&orgID)
	if err != nil {
		t.Fatalf("create org: %v", err)
	}

	inviteEmail := "invite-test@example.com"
	var invID string
	err = pool.QueryRow(ctx,
		`INSERT INTO organization_invitations (organization_id, email, role)
		 VALUES ($1, $2, 'member') RETURNING id`,
		orgID, inviteEmail,
	).Scan(&invID)
	if err != nil {
		t.Fatalf("create invitation: %v", err)
	}

	t.Cleanup(func() {
		_, _ = pool.Exec(ctx, `DELETE FROM memberships WHERE organization_id = $1`, orgID)
		_, _ = pool.Exec(ctx, `DELETE FROM organization_invitations WHERE id = $1`, invID)
		_, _ = pool.Exec(ctx, `DELETE FROM organizations WHERE id = $1`, orgID)
		_, _ = pool.Exec(ctx, `DELETE FROM auth_identities WHERE provider_sub = 'github-sub-invite-001'`)
		_, _ = pool.Exec(ctx, `DELETE FROM users WHERE lower(email) = lower($1)`, inviteEmail)
	})

	// ── Mock IdP ──────────────────────────────────────────────────────────────
	idp := idpServer(t, `{
		"sub": "github-sub-invite-001",
		"email": "invite-test@example.com",
		"email_verified": true,
		"name": "Invite Test User",
		"picture": ""
	}`)

	provider := &mockCallbackProvider{
		name:        "google",
		tokenURL:    idp.URL + "/token",
		userinfoURL: idp.URL + "/userinfo",
	}

	sessMgr := sessions.NewForTest()
	sm := sessMgr.SessionManager()

	stateCtx, _ := sm.Load(ctx, "")
	const testState = "invite-state-abc"
	sessMgr.SetOAuthState(stateCtx, testState)
	sessionToken, _, _ := sm.Commit(stateCtx)

	cfg := &config.Config{FrontendBaseURL: "https://app.example.com"}
	deps := &Deps{
		Cfg:      cfg,
		DB:       pool,
		Sessions: sessMgr,
		Users:    users.New(pool),
		Orgs:     organizations.New(pool),
		Providers: map[string]oauth.Provider{"google": provider},
	}

	r := New()
	r.Use(scsGinMiddleware(sm))
	r.GET("/auth/:provider/callback", deps.handleAuthCallback)

	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet,
		"/auth/google/callback?code=x&state="+testState, nil)
	req.AddCookie(&http.Cookie{Name: sm.Cookie.Name, Value: sessionToken})
	r.ServeHTTP(w, req)

	if w.Code != http.StatusTemporaryRedirect {
		t.Fatalf("expected 307, got %d: %s", w.Code, w.Body.String())
	}

	// Verify invitation was accepted.
	var acceptedAt *time.Time
	err = pool.QueryRow(ctx,
		`SELECT accepted_at FROM organization_invitations WHERE id = $1`, invID,
	).Scan(&acceptedAt)
	if err != nil {
		t.Fatalf("query invitation: %v", err)
	}
	if acceptedAt == nil {
		t.Fatal("invitation accepted_at is nil — invitation was not consumed")
	}

	// Verify membership row was created.
	var membershipCount int
	err = pool.QueryRow(ctx,
		`SELECT count(*) FROM memberships
		 WHERE organization_id = $1
		   AND user_id = (SELECT id FROM users WHERE lower(email) = lower($2))`,
		orgID, inviteEmail,
	).Scan(&membershipCount)
	if err != nil {
		t.Fatalf("query membership: %v", err)
	}
	if membershipCount == 0 {
		t.Fatal("membership row was not created after invitation acceptance")
	}
}

// mockCallbackProvider is a Provider whose Exchange and FetchUserInfo call an
// in-process httptest.Server acting as the IdP.
type mockCallbackProvider struct {
	name        string
	tokenURL    string
	userinfoURL string
}

func (m *mockCallbackProvider) Name() string { return m.name }

func (m *mockCallbackProvider) AuthCodeURL(state string, _ ...interface{ isAuthCodeOption() }) string {
	return "https://idp.example.com/auth?state=" + state
}

func (m *mockCallbackProvider) Exchange(_ context.Context, _ string) (*oauthToken, error) {
	return &oauthToken{AccessToken: "test-access-token"}, nil
}

func (m *mockCallbackProvider) FetchUserInfo(_ context.Context, _ *oauthToken) (*oauth.UserInfo, error) {
	resp, err := http.Get(m.userinfoURL) //nolint:noctx
	if err != nil {
		return nil, fmt.Errorf("mock FetchUserInfo: %w", err)
	}
	defer resp.Body.Close()

	var info struct {
		Sub           string `json:"sub"`
		Email         string `json:"email"`
		EmailVerified bool   `json:"email_verified"`
		Name          string `json:"name"`
		Picture       string `json:"picture"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&info); err != nil {
		return nil, err
	}
	return &oauth.UserInfo{
		ProviderSub:   info.Sub,
		Email:         info.Email,
		EmailVerified: info.EmailVerified,
		DisplayName:   info.Name,
		AvatarURL:     info.Picture,
	}, nil
}

